#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,json,hashlib,sys
BASE={'lite':'6acb643ee40954a53f2e71c86caea10969e986f8','full':'e778ce5baa7f39f7dcb7a229961089e9c1ea2632'}
TARGET={'lite':'101c44bbd5ca45ea805bfb344c9aae03adba5401','full':'2c97a97021f266d4f322bb71e1ac5c4ef2b767a6'}
PATCH_B64={'lite':'','full':'','full':''}
def blob(data): return hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
def ops(kind): return json.loads(zlib.decompress(base64.b64decode(PATCH_B64[kind])).decode())
def upgrade(raw,kind):
    got=blob(raw)
    if got!=BASE[kind]: raise ValueError(f'Unknown V189 {kind} blob expected {BASE[kind]} got {got}')
    lines=raw.decode('utf8').splitlines(keepends=True)
    for i1,i2,new in reversed(ops(kind)): lines[i1:i2]=new.splitlines(keepends=True)
    out=''.join(lines).encode('utf8')
    if blob(out)!=TARGET[kind]: raise ValueError(f'generated blob mismatch {blob(out)} != {TARGET[kind]}')
    return out

def main():
    if sys.argv[1:2]==['--full'] and len(sys.argv)==4:
        src,dst=map(Path,sys.argv[2:]); out=upgrade(src.read_bytes(),'full'); dst.write_bytes(out); print('V190 full Git blob:',blob(out)); return
    if len(sys.argv)==3:
        src,dst=map(Path,sys.argv[1:]); out=upgrade(src.read_bytes(),'lite'); dst.write_bytes(out); print('V190 lite Git blob:',blob(out)); return
    if len(sys.argv)==1:
        index=Path('index.html'); archive=Path('monarch_v190_lite.html'); raw=index.read_bytes(); got=blob(raw)
        if got==BASE['lite']:
            out=upgrade(raw,'lite'); index.write_bytes(out); archive.write_bytes(out)
        elif got==TARGET['lite'] and b'Original Restoration V190 LITE' in raw and b'function tickOriginalElevators(' in raw:
            if archive.exists() and archive.read_bytes()!=raw: raise ValueError('Refuse mismatched V190 archive')
            archive.write_bytes(raw)
        else: raise ValueError(f'Unknown index version; refusing overwrite: {got}')
        assert index.read_bytes()==archive.read_bytes(); assert blob(index.read_bytes())==TARGET['lite']; print('PASS V190 index/archive blob',blob(index.read_bytes())); return
    raise SystemExit('Usage: upgrade_v190.py [V189lite V190lite] | [--full V189full V190full]')
if __name__=='__main__': main()
